templates.property:
function property_LIB_SOLVENCY() public view returns (bool) {
    return asset.balanceOf(address(protocol)) >= _totalObligations();
}

function property_LIB_CONSERVATION() public view returns (bool) {
    return ghostIn == ghostOut + _held();
}

function property_LIB_SUPPLY_INTEGRITY() public view returns (bool) {
    return token.totalSupply() == _sumBalances();
}

function property_LIB_NO_UNDERFLOW() public view returns (bool) {
    return totalWithdrawn() <= totalDeposited() && totalRefunded() <= totalAllocated();
}

function property_LIB_GETTER_NO_REVERT() public returns (bool) {
    protocol.getProjects();
    protocol.getTokenAmounts(asset);
    return true;
}

function handler_attacker_setFee(uint256 fee) public {
    vm.prank(currentActor);            // a non-privileged actor
    try protocol.setFee(fee) { t(false, "unauthorized setFee succeeded"); } catch {}
}

function property_LIB_THIRD_PARTY_ISOLATION() public view returns (bool) {
    return _entitlementOf(victim) >= _victimEntitlementFloor;
}

function property_LIB_ROUNDTRIP_NO_PROFIT() public {
    uint256 shares = vault.convertToShares(a);
    lte(vault.convertToAssets(shares), a, "round-trip minted value");
}

function property_LIB_4626_INFLATION() public {
    if (vault.totalSupply() == 0) return;
    gt(vault.convertToShares(1e18), 0, "1e18 deposit rounds to 0 shares (inflation attack)");
}

function property_LIB_REWARD_SOLVENCY() public view returns (bool) {
    return rewardToken.balanceOf(address(protocol)) >= _totalOwedRewards();
}

function property_LIB_REWARD_CONSERVATION() public view returns (bool) {
    return ghostAccrued == ghostClaimed + _totalClaimable();
}

function property_LIB_AMM_K() public view returns (bool) {
    return _after.k >= _before.k;
}

function property_LIB_AMM_RESERVES_MATCH() public view returns (bool) {
    return reserve0() <= token0.balanceOf(address(pool))
        && reserve1() <= token1.balanceOf(address(pool));
}

function property_LIB_LEND_HEALTH() public view returns (bool) {
    return _collateralValue(actor) >= _debtValue(actor);
}

function property_LIB_LEND_NO_BAD_DEBT() public view returns (bool) {
    return _totalDebt() <= _totalBacking();
}

function property_LIB_LEND_INDEX_MONOTONE() public view returns (bool) {
    return _after.borrowIndex >= _before.borrowIndex;
}

function property_LIB_PERPS_ZERO_SUM() public view returns (bool) {
    return _totalLongPnl() + _totalShortPnl() + int256(_feePot()) == 0;
}

function property_LIB_PERPS_INSURANCE_NONNEG() public view returns (bool) {
    return _insuranceFund() >= 0;
}

function property_LIB_BRIDGE_MINT_EQ_LOCK() public view returns (bool) {
    return ghostMinted <= ghostLocked;
}

function handler_replay(bytes32 id) public {
    if (!_processed(id)) return;
    try protocol.execute(id) { t(false, "replay of processed message succeeded"); } catch {}
}

function handler_priceUnderStale(uint256 amt) public {
    oracle.setStale(true);
    try protocol.borrow(amt) { t(false, "op priced off a stale oracle succeeded"); } catch {}
    oracle.setStale(false);
}

function property_LIB_ORACLE_NO_ATOMIC_PROFIT() public view returns (bool) {
    return _actorEquity(currentActor) <= _actorEquityFloor;
}

function property_LIB_NFT_SUPPLY() public view returns (bool) {
    return nft.totalSupply() <= MAX_SUPPLY;
}

function property_LIB_GOV_VOTES() public view returns (bool) {
    return _countedVotes(activeProposal) <= _snapshotSupply(activeProposal);
}

function handler_reexecute(uint256 id) public {
    if (!_executed(id)) return;
    try governor.execute(id) { t(false, "double-execute succeeded"); } catch {}
}

function handler_gatedOutOfPhase(uint256 amt) public {
    if (protocol.phase() == Phase.OPEN) return;
    try protocol.bid(amt) { t(false, "bid accepted outside OPEN phase"); } catch {}
}

function property_LIB_AUCTION_BID_MONOTONE() public view returns (bool) {
    return _after.highestBid >= _before.highestBid;
}

function property_LIB_RESTAKE_QUEUE() public view returns (bool) {
    return ghostQueued == ghostCompleted + _pendingWithdrawals();
}

function property_LIB_INTENT_PAYOUT() public view returns (bool) {
    return _actualOut(lastIntent) <= _authorizedOut(lastIntent);
}

function handler_reenter(uint256 amt) public {
    attacker.armReentry(address(protocol));   // re-enters withdraw() from the receive hook
    try protocol.withdraw(amt) {} catch {}
    // LIB-SOLVENCY / LIB-CONSERVATION checked after every sequence catches the corruption
}
